def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

primes = []
# We only need to check odd primes p, since p+q=800 (even) means p and q must have the same parity.
# Since p+q=800, if p=2, q=798 (not prime). So p and q must be odd.
# p < 400.
for p in range(3, 400):
    if is_prime(p):
        q = 800 - p
        if is_prime(q) and p < q:
            primes.append((p, q))

print(primes)
